import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.CNoGN0p1.js";const s="/phenoblend/assets/home.DmzbLHu3.png",f=JSON.parse('{"title":"Loading data","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/data.md","filePath":"tutorial/data.md"}'),i={name:"tutorial/data.md"};function l(r,e,d,h,p,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="loading-data" tabindex="-1">Loading data <a class="header-anchor" href="#loading-data" aria-label="Permalink to &quot;Loading data&quot;">​</a></h1><p>Users need to download three files from the <a href="https://hpo.jax.org/" target="_blank" rel="noreferrer">Human Phenotype Ontology (HPO)</a> website representing the ontology itself and the disease annotations. It is advisable to use the latest versions (updates are made about once every two months).</p><h2 id="hp-json" tabindex="-1">hp.json <a class="header-anchor" href="#hp-json" aria-label="Permalink to &quot;hp.json&quot;">​</a></h2><p>This is the file with the ontology data. Note that only the <code>hp.json</code> format is supported. Do not try to use the OBO or the OWL file.</p><ul><li><a href="https://hpo.jax.org/data/ontology" target="_blank" rel="noreferrer">HPO ontology file downloads</a></li></ul><h2 id="phenotype-hpoa" tabindex="-1">phenotype.hpoa <a class="header-anchor" href="#phenotype-hpoa" aria-label="Permalink to &quot;phenotype.hpoa&quot;">​</a></h2><p>This is the file that contains the HPO-based disease models for Mendelian diseases. Click on the orange button entitled <code>DOWNLOAD HPO ANNOTATIONS</code></p><ul><li><a href="https://hpo.jax.org/data/annotations" target="_blank" rel="noreferrer">HPO Annotation download</a></li></ul><h2 id="genes-to-disease" tabindex="-1">Genes to Disease <a class="header-anchor" href="#genes-to-disease" aria-label="Permalink to &quot;Genes to Disease&quot;">​</a></h2><p>This is the file that links genes to the HPO disease annotation models. It is available on the same page as the <code>phenotype.hpoa</code> file. Click on the green button entitled <code>GENES TO DISEASE</code>.</p><div class="tip custom-block"><p class="custom-block-title">File downloads</p><p>It is advisable (but not required) to download all three files to the same directory. Create a directory called <code>HPO Data</code> (or whatever you like) and download all three files there before running phenoblend.</p></div><p><img src="'+s+'" alt="Home: Load the required data files"><em>Figure 1. After successfully loading the three required input files, the home page will look like this.</em></p>',12)])])}const m=t(i,[["render",l]]);export{f as __pageData,m as default};
